def norm(s): return ''.join(c for c in re.sub('<[^>]+>','',s) if not c.isspace() and unicodedata.category(c)[0] not in 'PZS')
def v(e,p,quote,target,correct,*wrong):
    q(e,p,'vocabulary',quote,target,f'原句中「{target}」的意思是甚麼？',correct,f'本句「{target}」解作「{correct}」。',*wrong)
def q(e,p,ability,quote,target,stem,correct,explanation,*wrong,support=None):
    assert len(wrong)==3
    ROWS.append(dict(e=e,p=p,ability=ability,quote=quote,target=target,stem=stem,correct=correct,explanation=explanation,wrong=wrong,support=support))
