q(7,6,'meaning','聖人無常師','無常師','「無常師」應如何理解？','不固定只向一位老師學習','下文列孔子從多位老師學習，說明可廣泛從師。',('聖人不需要任何老師','後文孔子從師例子直接否定此說。'),('老師必須每天更換一次','無固定老師並非按日更換規則。'),('不准向能力高的人學習','原文反對固定門檻，並非排除能力高者。'),support=(8,7))
q(7,2,'theme','道之所存，師之所存也','擇師','依本文，擇師應看重甚麼？','對方有可供學習的道理或專長','年齡官位不能代替聞道先後與術業專長。',('年齡必須比自己大','生於我後而聞道在先者亦可為師。'),('官位必須與自己相當','無貴無賤，官位不應設限。'),('整體能力必須在每方面都勝過自己','師不必賢於弟子，專長可互學。'),support=(8,5))
q(7,3,'technique','古之聖人，其出人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學於師','古聖／今眾','這組對比主要批評甚麼？','才智不及聖人卻恥於從師的態度','聖人尚肯學，一般人反以求學為恥，反差揭示其不明智。',('聖人向別人請教有損名望','作者肯定聖人從師，不是貶低。'),('今人出生太晚所以無法學習','問題在態度，非出生年代的宿命。'),('所有孩子都不願意上學','比較對象並非孩子。'),support=(11,0))
v(8,1,'恒惴慄','惴慄','恐懼不安',('悠閒快樂','此處寫被貶後的不安，與後來解脫相對。'),('身體寒冷','惴慄著重心理恐懼，不是天氣冷。'),('驕傲自滿','語境是受貶處境，非自得。'))
v(8,1,'窮迴溪','窮','走到盡頭',('生活貧困','此處帶迴溪作賓語，指走到盡頭。'),('溪水匱乏','說遊人的行程，非水量。'),('停止遊覽','窮是走盡，不是半途停止。'))
v(8,2,'緣染溪','緣','沿着',('因緣緣分','緣帶溪名，表示行進路線。'),('因為','此處沿溪行，不是在解釋原因。'),('攀上溪水','沿着溪流不等於向上攀水。'))
v(8,5,'然後知吾嚮之未始遊','嚮','從前、過往',('向着','此處指過往時段，非方向。'),('嚮往','作時間詞，不是心理動詞。'),('響亮','不可把嚮當聲響的響。'))
v(8,5,'故為之文以志','志','記述、記錄',('志向','志在此是寫作目的的動詞。'),('辨認標記','作者作文記述遊歷，非辨識標誌。'),('牢記仇恨','內容為宴遊所得，非記恨。'))
q(8,5,'meaning','心凝形釋，與萬化冥合','心凝形釋','這兩句最準確的理解是甚麼？','心神安定、形體束縛似解開，與自然融和','這是精神上的忘我超脫，不是肉身實際消失。',('肉身變成山石而永久消失','把精神境界當成物理變化。'),('更加恐懼，無法感受自然','與心凝形釋的安定開解相反。'),('酒醒後立即離山返回城中','原文說猶不欲歸，且此句重心為精神所得。'),support=(9,3))
q(8,5,'theme','然後知吾嚮之未始遊，遊於是乎始','始得','作者說從前「未始遊」，主要強調甚麼？','此次才領悟真遊之趣並得到精神解放','前文明寫多次舊遊，未始遊應理解為未得真趣。',('以前從來沒有離開住所','第一段已詳述舊遊，不能按字面否定。'),('此次才學會飲酒與睡覺','舊遊已有飲酒睡臥，關鍵不是動作技能。'),('此後只可遊西山而不可去別處','原文沒有制定以後的遊覽禁令。'),support=(9,1))
q(8,3,'technique','若垤若穴，尺寸千里','山下景物','把山下群山窪地寫得如蟻垤洞穴般低小，有何作用？','從周圍景物反襯西山高峻','以山下低小側寫西山之高，反襯與側面描寫可同時成立。',('證明群山真的縮小成蟻穴','這是登高俯視的感受，非地形真變小。'),('直接逐字量出西山高度','沒有提供山高的實際數字。'),('突出西山比群山低矮','襯托方向相反。'),support=(14,1))
v(10,1,'非兵不利，戰不善','兵','兵器',('士兵','與利搭配，指兵器鋒利，非士兵性情。'),('軍隊','本句兵指器械；與後文秦兵又至不同。'),('戰爭','戰不善另說作戰，兵不利指兵器。'))
v(10,2,'子孫視之不甚惜，舉以予人','舉','全部拿出',('舉起雙手','拿出的是土地，不是身體動作。'),('推舉人才','對象是祖先得來的土地，非人物。'),('舉辦儀式','原句指割地給秦，非舉行典禮。'))
v(10,3,'暴秦之欲無厭','厭','滿足',('厭惡','無厭指欲望永不滿足，非沒有憎惡。'),('疲倦','說秦的貪欲，不是體力疲勞。'),('壓迫','此處厭不是壓的動作。'))
v(10,5,'後秦擊趙者再','再','兩次',('再次而不論次數','古義明指兩次，不只是又一次。'),('多次而無法計數','再在此是確切次數。'),('將來才發生','原文敘既往戰事，非未來時態。'))
v(10,7,'而從六國破亡之故事','故事','舊事、先例',('虛構小說','這裏借六國歷史作鑑戒，非小說。'),('故意生事','故事是一個名詞，不是故意惹事。'),('交往多年的朋友','不可拆作故友之事。'))
q(10,1,'meaning','不賂者以賂者喪','不賂者','作者如何解釋不賂秦國家也滅亡？','賂秦者削弱滅亡，使它們失去強援','下文明言失強援、不能獨完，不能說六國全都直接賂秦。',('它們其實都直接割地賂秦','本文明分賂者與不賂者。'),('它們完全不曾抵抗秦國','燕趙用兵有成效，並非從未抵抗。'),('只因兵器都不夠鋒利','開頭已否定這是總敗因。'),support=(8,1))
q(10,7,'theme','茍以天下之大，而從六國破亡之故事，是又在六國下矣','借古諷今','結尾從六國轉到「天下之大」，寄託甚麼勸告？','勸當世統治者汲取教訓，不重蹈畏敵賂敵覆轍','以統一大國對照昔日諸侯，借古警誡當世。',('勸當世繼續割地以換取永久和平','文章論證割地求安反促滅亡。'),('證明六國歷史與當世毫無關係','結尾特意建立古今關係。'),('主張無論情況如何都不需人才','前文明倡封謀臣、禮奇才。'),support=(8,0))
q(10,3,'technique','以地事秦，猶抱薪救火，薪不盡，火不滅','抱薪救火','在這個比喻中，添柴救火對應甚麼道理？','割地求安反增秦欲與秦力，使侵略加劇','土地如柴，侵略野心如火；投入土地不能消除侵略。',('割地能立刻使秦永遠停戰','與火不滅及侵之愈急相反。'),('秦國兵器主要用木柴製造','比喻說策略後果，不是軍工材料。'),('諸侯需要先燒毀土地才能自保','火喻侵略，非實行焚地戰術。'),support=(13,0))
v(12,1,'獨酌無相親','相親','親近的友伴',('安排婚姻的見面','此處指無知心友伴，非現代相親。'),('父母親人','詞義不限血親，重在可相伴者。'),('彼此親吻','無相親說缺乏友伴，非親密動作。'))
v(12,1,'月既不解飲','解','懂得',('解除','此處是不懂飲酒，非取消飲酒。'),('解開繩結','句中沒有可解開的物件。'),('解送','解帶飲作理解內容，不是押送。'))
v(12,2,'暫伴月將影','將','和',('即將','將連接月與影，非表示未來。'),('帶領軍隊','此處不是動詞將兵。'),('將軍','月與影之間需要連接詞，非職銜。'))
v(12,2,'行樂須及春','及','趁着',('比得上','指趁春日行樂，非比較優劣。'),('牽連','句中沒有被牽連的對象。'),('等待直到','是把握春日，不是延後等待。'))
v(12,3,'相期邈雲漢','雲漢','銀河',('漢朝','雲漢為天上銀河，非朝代。'),('漢水','結尾相約遙遠天際，非地上河流。'),('雲中的男子','不能拆字為雲與漢子。'))
q(12,1,'meaning','舉杯邀明月，對影成三人','三人','「三人」具體指誰？','詩人、明月和影子','三人由我、月、影想像組成，並非真有兩位客人到來。',('詩人與兩位酒友','原句無真實酒友，開頭明說獨酌。'),('三位途經花園的旅人','原詩未寫旅人出現。'),('月亮及兩個影子','不可漏掉舉杯的詩人本人。'))
q(12,1,'theme','月既不解飲，影徒隨我身','月影不解','這兩句怎樣承接「對影成三人」的情緒？','想像有伴後，再意識到月影不解人意','月不能飲、影只隨身，現實無友的孤寂重新顯現。',('證實知己已來分享內心','月影並非能理解詩人的真人。'),('從此全詩只剩毫無轉折的歡樂','這裏已轉失落，後文情緒亦有起伏。'),('表示詩人再也不願與月影相伴','下文仍說暫伴月將影。'),support=(6,0))
q(12,1,'technique','舉杯邀明月','邀明月','「邀」字怎樣使場景生動？','把月亮當作可邀飲的友伴，賦予人的角色','以人的交往方式對待月亮，擬人使冷清場景在想像中熱鬧。',('精確記錄月亮落入杯中的科學過程','此為想像與擬人，非物理過程。'),('用月亮借代皇帝發布命令','本句邀月為伴，無皇帝命令。'),('反問月亮是否同意飲酒','原句不是疑問句。'),support=(8,0))
v(13,1,'花近高樓傷客心','客心','客居異地的詩人之心',('來訪賓客的共同心情','客指詩人客居身份，非宴會賓客群體。'),('招待客人的禮節','心是內心感受，非禮制。'),('仇敵的意圖','客不是敵，不能望文改義。'))
v(13,1,'萬方多難此登臨','萬方','天下各處',('一萬種方法','方在此為地方，不是辦法。'),('一萬名方士','並非計算人物數量。'),('萬里以外的一個地方','指四方天下，不限一處遠地。'))
v(13,2,'可憐後主還祠廟','可憐','可嘆',('十分可愛','古義表感嘆，非可愛。'),('值得效法','詩人對後主受祀帶諷慨，非立為榜樣。'),('允許憐惜','可憐是整體詞義，不拆作准許行為。'))
v(13,2,'日暮聊為梁甫吟','聊','姑且',('聊天','聊修飾吟詩，非談話動作。'),('依賴','這裏說姑且藉吟詩自遣。'),('毫不遲疑地','聊含姑且自遣意味，非果決。'))
v(13,2,'西山寇盜莫相侵','莫','不要',('沒有任何人','本句警告侵略者不要侵犯，非無人侵略。'),('傍晚','莫此處不是暮的通假義。'),('大概','是勸止語氣，非猜測。'))
q(13,1,'meaning','花近高樓傷客心，萬方多難此登臨','傷客心','面對樓邊繁花，詩人何以仍然傷心？','天下多難使客居的詩人憂國傷時','第二句點出國难，是傷心根由，花景本可悅目。',('因眼前所有花木都已枯死','原句未寫枯花，書中解作繁花樂景。'),('因他只在乎花園是否屬於自己','無土地佔有或私產爭奪之意。'),('因登樓完全不能看到遠方','下聯正展開遠望山川。'),support=(5,0))
q(13,2,'theme','北極朝廷終不改，西山寇盜莫相侵','朝廷／寇盜','這兩句如何表明詩人的政治立場？','對唐室抱有信念，並反對外敵侵擾','穩定的北極比朝廷，莫相侵是對侵略者的警告；信念與憂患可並存。',('認定朝廷必亡，歡迎外敵入侵','與終不改和莫相侵都相反。'),('只評論星象而不涉及國事','朝廷、寇盜明確把星象連到國事。'),('完全否認天下存在任何危難','前文明言萬方多難，不能抹去憂患。'),support=(5,0))
q(13,1,'technique','花近高樓傷客心','花與客心','美麗春花與傷心相連，主要產生甚麼表達效果？','以樂景反襯憂國的哀情','景物美好而內心憂傷，反差加深傷時之感。',('以衰敗景物直接渲染荒涼','花景本美，並未寫作衰敗。'),('以喜悅心情證明國難已解','傷客心不等於喜悅，國難仍在。'),('以誇張數字量出樓宇高度','原句沒有誇大的數字。'),support=(7,0))
v(14,1,'千古風流人物','風流人物','有功業的傑出英雄',('男女關係放縱的人','此處讚歷史英雄，非現代情愛貶義。'),('隨水漂流的旅人','不可拆作風與水流的字面景物。'),('衣着時髦的遊客','風流指才具功業，不是潮流打扮。'))
v(14,1,'故壘西邊','故壘','舊營壘',('已故戰士','故壘是古戰場建築，非人物。'),('故鄉城門','故為舊，不能逕解詩人故鄉。'),('新築城牆','舊與新的時間方向相反。'))
v(14,2,'故國神遊','故國','赤壁故地、三國古戰場',('詞人的出生地','此處神遊三國故地，不是返鄉。'),('已滅亡的北宋','不能把懷古對象誤改為北宋亡國。'),('所有外國','故國有特定古戰場語境，非外國總稱。'))
v(14,2,'早生華髮','華髮','花白頭髮',('華麗髮飾','華髮指斑白頭髮，非首飾。'),('光彩照人的容貌','句中感嘆早衰，非讚美容貌。'),('茂密黑髮','頭髮顏色與原詞義相反。'))
v(14,2,'一尊還酹江月','酹','灑酒祭奠',('痛飲至醉','酹是灑酒寄懷，不是把酒全喝下。'),('斟滿酒杯','斟酒與把酒灑出祭奠不同。'),('用水洗杯','對象為酒與江月寄懷，非清潔器具。'))
q(14,2,'meaning','談笑間、檣櫓灰飛煙滅','談笑間','「談笑間」對周瑜形象有何作用？','表現儒將指揮從容、破敵有方','談笑自若與曹軍迅速覆滅相連，突出周瑜才能。',('表現他因恐懼而不敢指揮','從容談笑與畏縮相反。'),('說明他完全不知道戰爭發生','句中把談笑與破敵相連，非置身事外。'),('證明他只會說笑而沒有戰功','曹軍覆滅正顯示功業。'),support=(5,0))
q(14,2,'theme','多情應笑我，早生華髮','懷古與自傷','詞人懷想周瑜後寫自己華髮，主要抒發甚麼感慨？','英雄年少功成，反照自己年長而抱負未酬','周瑜的風采功業與自身遭際形成對照，懷古連到身世。',('自己戰功遠勝周瑜而自滿','書中解為功業未成的自傷。'),('只為記錄三國史實而毫無個人感受','笑我、華髮明顯轉入自身。'),('認為所有英雄都毫無才華','前文讚周瑜與豪傑，並非否定。'),support=(5,0))
q(14,1,'technique','捲起千堆雪','雪','本句以「雪」寫浪花，運用甚麼相似點？','白色與堆湧的形態','雪借喻白色浪花，使波濤捲起的形象鮮明。',('江水真的結冰下雪','雪是喻體，不能直接當天氣實況。'),('雪的寂靜證明江水毫無動態','捲起寫強烈動勢，非靜止。'),('用雪的味道說明江水甘甜','比喻依顏色形態，非味覺。'),support=(7,0))
v(15,1,'最難將息','將息','調養休息',('將要呼吸','將息是一個詞，不可逐字誤拆。'),('停止尋找','將息說調養身體，非停止尋覓。'),('息滅風聲','休養主體為人，非控制天氣。'))
v(15,1,'怎敵他晚來風急','敵','抵擋',('敵人','敵在此作動詞，非人物稱呼。'),('敵視','酒不能抵寒風，非懷敵意。'),('相等的數量','是抵禦力量，不是數量比較。'))
v(15,2,'滿地黃花堆積','黃花','菊花',('黃色紙花','此處為秋日菊花意象，非紙製花。'),('稻田成熟的稻穗','黃花不是農作收成。'),('所有黃顏色物品','詞義有特定花種，非顏色物品總稱。'))
