def flatten(x):
    if isinstance(x,str): return [x]
    if isinstance(x,list): return [s for v in x for s in flatten(v)]
    return []

def locate(e,p,b,anchor):
    essay=DATA[e-1]
    # Match the actual PDF text: the JSON organization index is never used as a page offset.
    # Original blocks may be broken by inline note numbers; strip those when matching.
    def source_norm(s): return re.sub(r'\d+','',norm(s))
    candidates=[]
    for idx,text in enumerate(PAGES):
        if norm(essay['name']) not in norm(text[:180]): continue
        clean=source_norm(text)
        if source_norm(anchor) in clean:
            score=0
            if '原文與語譯' in text: score+=30
            if source_norm(b[1][:45]) in clean: score+=15
            if norm(DATA[e-1]['pages'][p]['title']) in norm(text[:300]): score+=5
            candidates.append((score,idx+1))
    assert candidates,(e,p,anchor,'PDF anchor not found')
    candidates.sort(reverse=True)
    score,page=candidates[0]
    assert score>=30,(e,p,anchor,candidates,'No original-text page found')
    assert len(candidates)==1 or candidates[1][0]<score,(e,p,anchor,candidates,'Ambiguous PDF page')
    footer=re.search(r'(\d+)\s*$',PAGES[page-1])
    assert footer,(page,'No printed footer')
    return page,int(footer.group(1))

out=[]
counts=collections.Counter()
for row in ROWS:
    e,p=row['e'],row['p']; essay=DATA[e-1]; blocks=essay['pages'][p]['blocks']
    matches=[(i,b) for i,b in enumerate(blocks) if b[0]=='annot' and norm(row['quote']) in norm(b[1])]
    assert len(matches)==1,(e,p,row['quote'],'source quote mismatch')
    k,b=matches[0]; source_path=f'$[{e-1}].pages[{p}].blocks[{k}]'
    pdfpage,printed=locate(e,p,b,row['quote'])
    evidence={'blockPath':source_path,'text':b[1]}
    if row['ability']=='vocabulary':
        meanings=[v[1] for v in b[2] if v[0]==row['target']]
        assert row['correct'] in meanings,(e,row['target'],row['correct'],meanings)
        evidence['meaning']=row['correct']
        # The actual PDF must also contain the reviewed definition, not merely the original quote.
        assert norm(row['correct']) in norm(PAGES[pdfpage-1]),(e,row['quote'],row['correct'],pdfpage,'PDF definition missing')
    if row['support']:
        sp,sk=row['support']; sb=essay['pages'][sp]['blocks'][sk]
        evidence['interpretationBlockPath']=f'$[{e-1}].pages[{sp}].blocks[{sk}]'
        evidence['interpretationText']='\n'.join(flatten(sb[1]))
        fragments=[s for s in flatten(sb[1]) if len(norm(s))>=18]
        support_pages=[]
        for pi,pt in enumerate(PAGES):
            if norm(essay['name']) != norm(pt.split('\n')[0]): continue
            matched=[f for f in fragments if norm(f[:28]) in norm(pt)]
            if matched: support_pages.append({'pdfPage':pi+1,'printedPage':int(re.search(r'(\d+)\s*$',pt).group(1)), 'anchor':matched[0][:28]})
        assert support_pages,(e,p,'Interpretation not found in PDF')
        evidence['interpretationPdfLocations']=support_pages
    counts[e]+=1; seq=counts[e]; identifier=f'q-e{e:02d}-exp-{seq:03d}'
    choices=[(row['correct'],row['explanation'])]+list(row['wrong'])
    # Deterministic rotation avoids answer-position cues; content and distractors are hand-authored.
    shift=(seq+e)%4; choices=choices[shift:]+choices[:shift]
    answer=next(chr(97+i) for i,c in enumerate(choices) if c[0]==row['correct'])
    assert len({c[0] for c in choices})==4
    item=dict(id=identifier,version=1,memoryId=f'm-e{e:02d}-exp-{seq:03d}',essayIds=[f'essay-{e:02d}'],ability=row['ability'],quote=row['quote'],target=row['target'],stem=row['stem'],choices=[dict(id=chr(97+i),text=c[0],explanation=c[1]) for i,c in enumerate(choices)],answerId=answer,explanation=row['explanation'],source=dict(title='文言詩詞・十六篇復習書（附修辭與寫作手法）',essayTitle=essay['name'],section=essay['pages'][p]['title'],pdfPage=pdfpage,printedPage=printed,blockPath=source_path,version='2026-09-14',pdfUrl='/content/sources/revision-book.pdf',anchor=row['quote']),status='reviewed',active=True,summary=row['correct'],misconception=row['wrong'][0][1],difficulty='foundation',tags=[row['ability'],'revision-book-authored'],review=dict(method='source-aligned-agent-review',reviewedAt='2026-09-19',officialExamQuestion=False,sourceEvidence=evidence,checks=['quote-in-JSON-block','quote-on-actual-PDF-page','printed-footer-read','one-keyed-answer','four-distinct-options','targeted-distractor-explanations'],scope='依本地復習書逐題核對；不是官方真題或官方評分。'))
    out.append(item)
assert len(out)==104
assert all(n==8 for n in counts.values()) and len(counts)==13
pathlib.Path('web-study/content').mkdir(parents=True,exist_ok=True)
pathlib.Path('web-study/content/expansion-draft.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
report={'questionCount':len(out),'essayCount':len(counts),'abilities':dict(collections.Counter(q['ability'] for q in out)),'coverage':[{'essayId':f'essay-{e:02d}','title':DATA[e-1]['name'],'count':counts[e],'pdfPages':sorted({q['source']['pdfPage'] for q in out if q['essayIds']==[f'essay-{e:02d}']})} for e in counts],'sourceSha256':{n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in ['學生內容.json','文言詩詞_十六篇復習書_附修辭與寫作手法.pdf']},'limitations':['每篇8題為基礎覆蓋，非766詞解全面題化。','未製作跨篇比較、手法附錄專項及所有多義詞變式。','有分歧的奉、瓠落、絖、無情遊、玉壺、星如雨、憔悴損不設唯一詞義題。','內容核對基準為指定本地復習書，尚不等於逐項核驗官方原典及評分。']}
pathlib.Path('tools/question-bank/expansion-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(report,ensure_ascii=False,indent=2))


